// Data contract for files in /public/data, generated by pipeline/export_web_data.py

export type PopObs = {
  year: number;
  pop: number | null;          // census count as printed (null = place listed without a count)
  status: "observed" | "not_listed";
  quality: "A" | "B" | "C";    // A: two independent readings agree; B: single reading, well-formed; C: single reading with OCR warnings
  sources: string[];           // source table ids, e.g. "1950_T7"
  readings?: { table: string; page: number; value: number | null }[];
  note?: string;
};

export type RailYear = { year: number; dist_km: number | null; served: boolean };

export type Town = {
  id: string;
  name: string;
  county: string;
  lat: number;
  lon: number;
  coord_source: string;        // "census2020_place" | "usgs_gnis"
  gaz_id: string;
  coord_match: string;         // how the name was matched
  census2020_place: string | null;
  pops: PopObs[];
  pop2010: number | null;
  pop2020: number | null;
  rail: RailYear[];            // distance to nearest documented track for each Atack benchmark + 2020 TIGER
  first_served_benchmark: number | null;   // first Atack benchmark year with track within threshold
  arrival_interval: [number | null, number] | null;
  served_2020: boolean | null;
  metrics: {
    hub_dist_km_1911: number | null;      // network km to the nearest 1900 city of 10,000+ (Atack 1911 network)
    betweenness_1911: number | null;
    node_degree_1911: number | null;
    main_component_1911: boolean | null;
    hub_dist_km_1889: number | null;
  };
  outcomes: {
    growth_1910_1970: number | null;     // log points
    growth_1910_2020: number | null;
    growth_1890_1910: number | null;
    persisted_2020: boolean;             // matched to a 2020 census place
    peak_year: number | null;
    declined_from_peak_pct: number | null;
  };
  flags: string[];
};

export type Summary = Record<string, unknown>;
